window.VO = [{"id":"n01","text":"You're the witness. Remember the man who stole your rings.","at":0.24,"t0":0.12,"t1":3.125},{"id":"n02","text":"Grey hair. A moustache.","at":6.95,"t0":3.475,"t1":5.04},{"id":"n03","text":"Now the police show you six men.","at":12.48,"t0":6.24,"t1":7.99},{"id":"n04","text":"Which one is him?","at":16.68,"t0":8.34,"t1":9.44},{"id":"n05","text":"Number four? That's who the women picked, in London, in eighteen ninety-six.","at":23.28,"t0":11.64,"t1":15.81},{"id":"n06","text":"His name was Adolf Beck. He wasn't the swindler.","at":32.82,"t0":16.41,"t1":19.34},{"id":"n07","text":"He was the only man in that line with grey hair and a moustache.","at":40.08,"t0":20.04,"t1":23.78},{"id":"n08","text":"The women remembered grey hair and a moustache. The line gave them only one man to match.","at":48.26,"t0":24.13,"t1":29.285},{"id":"n09","text":"Beck went to prison twice, until the real swindler was caught in nineteen oh four.","at":59.97,"t0":29.985,"t1":34.56},{"id":"n10","text":"His case helped create England's Court of Criminal Appeal.","at":70.12,"t0":35.06,"t1":37.98},{"id":"n11","text":"Today, every face in a fair lineup should fit the description.","at":76.96,"t0":38.48,"t1":41.755}];
